// Learning Typescript
// Basic building blocks of typescript
// 1. Primitive types
// a. number
const age = 20;
// b. string
let name1 = "John";
// c. boolean
let isMarried = false;
// d. void
function sayHello() {
    console.log("Hello there, let's learn typescript");
}
sayHello();
// e. null
let nullValue = null;
// f. undefined
let undefinedValue = undefined;
// 2. Arrays
let names = ["John", "Doe", "Smith"];
names.push("Anant");
console.log(names);
let ages = [20, 30, 40];
ages.push(50);
console.log(ages);
// 3. Functions
function calculateMyAge(age) {
    return age + 1;
}
function getName(name) {
    return name;
}
let firstname = getName("Anant");
console.log(firstname);
console.log(calculateMyAge(20)); // 201
// 4. Objects
let person = {
    firstname: "Anant Jain",
    age: 34
};
console.log(person);
let employee1 = {
    name: "Anant Jain",
    age: 34,
    isMarried: true
};
